mapper.select:
SELECT STRFTIME('%Y-%m-%d %H:%M:%S', U.REG_DATE) AS regDate, STRFTIME('%Y-%m-%d %H:%M:%S', U.UPDATE_DATE) AS updateDate, U.USER_NO AS userNo, U.ENABLED AS enabled, U.ROLE AS role, U.PROVIDER AS provider, U.ID AS id, U.EMAIL AS email, U.NICKNAME AS nickname, U.DESCRIPTION AS note, U.PROFILE_IMG_PATH AS profileUrl FROM MB_USER U WHERE STRFTIME('%Y-%m-%d', U.REG_DATE) = #{date}
AND ( UPPER(U.ID) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.EMAIL) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.NICKNAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.PROVIDER) LIKE '%' || UPPER(#{keyword}) || '%' )
ORDER BY U.USER_NO DESC LIMIT 20 OFFSET #{offset}
